/* ISR-shared variables: must be volatile for safe cross-boundary access */
static volatile uint32_t g_sample_value = 0U;
static volatile bool     g_sample_ready = false;

/**
 * @brief   PIT Channel 0 Interrupt Service Routine
 */
void PIT_IRQHandler(void)
{
    /* Check and clear the timer flag */
    if (PIT_GetStatusFlags(PIT, kPIT_Chnl_0) & kPIT_TimerFlag)
    {
        PIT_ClearStatusFlags(PIT, kPIT_Chnl_0, kPIT_TimerFlag);

        /* Sample digital input on PTC3 */
        g_sample_value = GPIO_PinRead(GPIOC, 3U);

        /* Signal main loop */
        g_sample_ready = true;
    }
}

int main(void)
{
    /* 1. Enable peripheral clocks */
    CLOCK_EnableClock(kCLOCK_Pit);
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_GpioC);
    CLOCK_EnableClock(kCLOCK_GpioE);

    /* 2. Configure pin multiplexing for GPIO mode */
    PORT_SetPinMux(PORTC, 3U, kPORT_MuxAsGpio);
    PORT_SetPinMux(PORTE, 24U, kPORT_MuxAsGpio);

    /* 3. Configure GPIO directions
     * PTC3: Digital Input
     * PTE24: Digital Output (LED)
     */
    gpio_pin_config_t pin_in_cfg = {kGPIO_DigitalInput, 0U};
    GPIO_PinInit(GPIOC, 3U, &pin_in_cfg);

    gpio_pin_config_t pin_out_cfg = {kGPIO_DigitalOutput, 0U};
    GPIO_PinInit(GPIOE, 24U, &pin_out_cfg);

    /* 4. Configure PIT Channel 0 for 10 ms period @ 48 MHz bus clock
     * Reload value = (48,000,000 Hz * 0.010 s) - 1 = 479,999
     */
    pit_config_t pit_cfg;
    PIT_GetDefaultConfig(&pit_cfg);
    pit_cfg.enableRunInDebug = false;
    PIT_Init(PIT, &pit_cfg);

    PIT_SetTimerLoadValue(PIT, kPIT_Chnl_0, 479999U);
    PIT_EnableInterrupts(PIT, kPIT_Chnl_0, kPIT_TimerInterruptEnable);
    PIT_StartTimer(PIT, kPIT_Chnl_0);

    /* 5. Enable PIT interrupt in NVIC */
    EnableIRQ(PIT_IRQn);

    /* 6. Main loop: consume samples and toggle LED if high */
    while (1)
    {
        uint32_t local_sample = 0U;
        bool     has_sample   = false;

        /* Critical section to safely read/clear ISR flag without race conditions */
        __disable_irq();
        if (g_sample_ready)
        {
            has_sample   = true;
            local_sample = g_sample_value;
            g_sample_ready = false;
        }
        __enable_irq();

        /* Act on newly acquired sample */
        if (has_sample && (local_sample != 0U))
        {
            GPIO_PortToggle(GPIOE, 1U << 24U);
        }
    }

    return 0; /* Should never reach here */
}

