int main(void)
{
    /* 1. Enable peripheral clocks before initialization */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_Spi0);

    /* 2. Configure pin multiplexing */
    /* PTC6 -> SPI0_SCK, PTC7 -> SPI0_MOSI, PTC4 -> SPI0_MISO */
    PORT_SetPinMux(PORTC, 6U, kPORT_MuxAlt3);
    PORT_SetPinMux(PORTC, 7U, kPORT_MuxAlt3);
    PORT_SetPinMux(PORTC, 4U, kPORT_MuxAlt3);
    /* PTC5 -> Manual CS control via GPIO */
    PORT_SetPinMux(PORTC, 5U, kPORT_MuxAsGpio);

    /* 3. Initialize CS GPIO pin as output, starting deasserted (logic high) */
    gpio_pin_config_t cs_pin_cfg = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 1U
    };
    GPIO_PinInit(GPIOC, 5U, &cs_pin_cfg);

    /* 4. Configure SPI0 Master */
    spi_master_config_t spi_cfg;
    SPI_MasterGetDefaultConfig(&spi_cfg);
    spi_cfg.baudRate_Bps   = 1000000U;        /* 1 MHz */
    spi_cfg.cpol           = false;           /* CPOL = 0 (Clock active high when idle) */
    spi_cfg.cpha           = false;           /* CPHA = 0 (Data captured on first clock edge) */
    spi_cfg.bitsPerFrame   = 8U;              /* 8-bit frame */
    spi_cfg.lsb            = false;           /* MSB first */

    /* Obtain source clock frequency for baud rate divisor calculation */
    uint32_t srcClock = CLOCK_GetFreq(kCLOCK_BusClk);
    if (srcClock == 0U) {
        srcClock = 24000000U; /* Fallback assumption if clock tree unconfigured */
    }

    SPI_MasterInit(SPI0, &spi_cfg, srcClock);

    /* 5. Prepare transaction data */
    const uint8_t tx_data[2] = {0x9FU, 0x00U};
    volatile uint8_t rx_data[2]; /* Volatile per NXP idiom for potential ISR/observe usage */

    spi_transfer_t xfer = {0};
    xfer.txData      = (uint8_t *)tx_data;
    xfer.rxData      = (uint8_t *)rx_data;
    xfer.dataSize    = sizeof(tx_data);
    xfer.configFlags = 0U;       /* Manual CS control, no frame assertion flag */

    /* 6. Assert CS (Active Low) */
    GPIO_PinWrite(GPIOC, 5U, 0U);

    /* 7. Execute blocking transfer */
    status_t status = SPI_MasterTransferBlocking(SPI0, &xfer);

    /* 8. Deassert CS */
    GPIO_PinWrite(GPIOC, 5U, 1U);

    /* Verify transfer status */
    if (status != kStatus_Success) {
        while (1) { } /* Stall on failure (application-dependent error handling) */
    }

    /* rx_data[0] and rx_data[1] now hold the 2 received bytes */

    while (1) {
        /* Main loop */
    }
}

