#include "fsl_port.h"
#include "fsl_uart.h"
#include "core_cm0plus.h"
#include <stdint.h>
#include <stddef.h>

int main(void)
{
    /* 1. Enable peripheral clock gates before initialization */
    CLOCK_EnableClock(kCLOCK_PortA);
    CLOCK_EnableClock(kCLOCK_Uart0);

    /* 2. Configure pin mux before using the peripheral */
    /* PTA1 = UART0_RX, PTA2 = UART0_TX. Alt2 is standard for UART on MCX/Kinetis */
    PORT_SetPinMux(PORTA, 1U, kPORT_MuxAlt2);
    PORT_SetPinMux(PORTA, 2U, kPORT_MuxAlt2);

    /* 3. Get default config, override fields, then init */
    uart_config_t uartConfig;
    UART_GetDefaultConfig(&uartConfig);
    uartConfig.baudRate_Bps = 115200U;
    uartConfig.parityMode   = kUART_ParityDisabled;
    uartConfig.stopBitCount = kUART_OneStopBit;
    uartConfig.dataBitsCount= kUART_EightDataBits;

    /* Use core/system clock as UART source (adjust if your board routes a different clock) */
    uint32_t uartSrcClock = CLOCK_GetFreq(kCLOCK_CoreSysClk);
    status_t status = UART_Init(UART0, &uartConfig, uartSrcClock);
    if (status != kStatus_Success)
    {
        /* Initialization failed: halt safely */
        while (1) {}
    }

    const char *msg = "Hello\r\n";
    const size_t msgLen = 7U;

    /* Main loop: blocking transmit + 1-second delay */
    while (1)
    {
        UART_WriteBlocking(UART0, (const uint8_t *)msg, msgLen);

        /* 1-second software delay using calibrated busy loop */
        uint32_t delayCycles = SystemCoreClock / 4U;
        for (volatile uint32_t i = 0; i < delayCycles; ++i)
        {
            __NOP();
        }
    }

    return 0;
}

