#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

#define TRANSFER_SIZE (512U)
#define DMA_CHANNEL   (0U)

/* Aligned buffers for efficient bus transactions */
__attribute__((aligned(32))) static uint8_t srcBuffer[TRANSFER_SIZE];
__attribute__((aligned(32))) static uint8_t dstBuffer[TRANSFER_SIZE];

int main(void)
{
    /* 1. Enable peripheral clock for DMA0 */
    CLOCK_EnableClock(kCLOCK_DMA0);

    /* 2. Initialize eDMA controller */
    edma_config_t edmaConfig;
    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);

    /* 3. Fill source buffer with index pattern (index & 0xFF) */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        srcBuffer[i] = (uint8_t)(i & 0xFFU);
    }

    /* 4. Configure memory-to-memory transfer */
    edma_transfer_config_t xferConfig = {0};
    xferConfig.srcAddr        = (uint32_t)srcBuffer;
    xferConfig.destAddr       = (uint32_t)dstBuffer;
    xferConfig.srcOffset      = 0U;
    xferConfig.destOffset     = 0U;
    xferConfig.minorLoopBytes = TRANSFER_SIZE;
    xferConfig.majorLoopCount = 1U;

    /* Apply TCD configuration to channel 0 */
    EDMA_SetTransferConfig(DMA0, DMA_CHANNEL, &xferConfig, 0U);

    /* 5. Start the eDMA transfer */
    EDMA_StartTransfer(DMA0, DMA_CHANNEL);

    /* 6. Poll until transfer completes */
    while (!(EDMA_GetChannelStatusFlags(DMA0, DMA_CHANNEL) & kEDMA_DmaDoneFlag))
    {
        /* Busy wait */
    }

    /* Clear the done flag */
    EDMA_ClearChannelStatusFlags(DMA0, DMA_CHANNEL, kEDMA_DmaDoneFlag);

    /* 7. Compare destination and source buffers */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        if (srcBuffer[i] != dstBuffer[i])
        {
            /* Mismatch detected: halt in infinite loop */
            while (1)
            {
                __NOP();
            }
        }
    }

    /* Success: halt in infinite low-power loop */
    while (1)
    {
        __WFI();
    }
}

