    CLOCK_EnableClock(kCLOCK_M7_DMAC);

    /* Initialize eDMA controller */
    edma_config_t edmaConfig;
    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);

    /* Fill source buffer with index pattern */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        srcBuffer[i] = (uint8_t)(i & 0xFFU);
    }

    /* Prepare transfer configuration */
    edma_transfer_config_t xferConfig;
    EDMA_PrepareTransfer(&xferConfig,
                         (void *)srcBuffer,
                         0U,
                         (void *)dstBuffer,
                         0U,
                         1U,                /* minorloopBytes */
                         TRANSFER_SIZE,     /* majorLoopCount */
                         kEDMA_TransferSize1Bytes,
                         0U);               /* tcdFlags */

    /* Create handle to satisfy EDMA_StartTransfer API */
    edma_handle_t dmaHandle;
    EDMA_CreateHandle(&dmaHandle, DMA0, DMA_CHANNEL, NULL, NULL);

    /* Apply TCD configuration to channel 0 */
    EDMA_SetTransferConfig(DMA0, DMA_CHANNEL, &xferConfig, NULL);

    /* Start the eDMA transfer via software trigger */
    EDMA_StartTransfer(&dmaHandle);

    /* Poll until transfer completes */
    while (!(EDMA_GetChannelStatusFlags(DMA0, DMA_CHANNEL) & kEDMA_DoneFlag))
    {
        /* Busy wait */
    }

    /* Clear the done flag */
    EDMA_ClearChannelStatusFlags(DMA0, DMA_CHANNEL, kEDMA_DoneFlag);

    /* Compare destination and source buffers */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        if (srcBuffer[i] != dstBuffer[i])
        {
            /* Mismatch detected: halt in infinite loop */
            while (1)
            {
                __NOP();
            }
        }
    }

    /* Success: halt in infinite low-power loop */
    while (1)
    {
        __WFI();
    }

    return 0;
}

