/* Simple software delay loop calibrated to roughly 500 ms */
static void SoftwareDelay_500ms(void)
{
    /* 
     * Busy-wait loop count calibrated for typical Cortex-M7 execution speed.
     * Each iteration consumes approximately 4 CPU cycles (decrement + branch + nop).
     * Adjust constant if exact 500ms is required after measuring core frequency.
     */
    volatile uint64_t loops = 250000000ULL; 
    while (loops-- > 0U)
    {
        __asm volatile ("nop");
    }
}

int main(void)
{
