#define SENSOR_I2C_SLAVE_ADDR   0x68U
#define SENSOR_WHO_AM_I_REG     0x75U
#define LPI2C_BAUD_RATE_BPS     400000U

/* Standard I2C pad config for RT1170: Open drain enabled, pull-up enabled,
   slow slew rate, drive strength X6, hysteresis enabled, pull select = 1 */
#define LPI2C_I2C_PAD_CONFIG    0x110B0U

static volatile uint8_t g_sensorWhoAmI = 0U;

int main(void)
{
    /* 1. Enable peripheral clocks before initialization */
    CLOCK_EnableClock(kCLOCK_Lpi2c1);
    CLOCK_EnableClock(kCLOCK_Iomuxc);

    /* 2. Configure pin multiplexing and pad settings for LPI2C1 */
    /* SCL: GPIO_AD_08 -> LPI2C1_SCL */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 0U);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_08_LPI2C1_SCL, LPI2C_I2C_PAD_CONFIG);

    /* SDA: GPIO_AD_09 -> LPI2C1_SDA */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 0U);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_09_LPI2C1_SDA, LPI2C_I2C_PAD_CONFIG);

    /* 3. Initialize LPI2C Master */
    lpi2c_master_config_t lpi2cConfig;
    LPI2C_MasterGetDefaultConfig(&lpi2cConfig);
    lpi2cConfig.baudRate_Bps = LPI2C_BAUD_RATE_BPS;

    /* Retrieve the root clock frequency driving LPI2C1.
       Typical RT1170 default boot config routes 24MHz OSC to this peripheral. */
    uint32_t lpi2cSourceClock = CLOCK_GetRootClockFreq(kCLOCK_RootLpi2c1);

    status_t status = LPI2C_MasterInit(LPI2C1, &lpi2cConfig, lpi2cSourceClock);
    if (status != kStatus_Success)
    {
        /* LPI2C initialization failed */
        while (1) {}
    }

    /* 4. Set up combined write-then-read transfer for WHO_AM_I register */
    lpi2c_master_transfer_t xfer = {0};
    xfer.slaveAddress   = SENSOR_I2C_SLAVE_ADDR;
    xfer.direction      = kLPI2C_Read;     /* SDK handles internal write for subaddress when subaddressSize > 0 */
    xfer.subaddress     = SENSOR_WHO_AM_I_REG;
    xfer.subaddressSize = 1U;
    xfer.data           = (uint8_t *)&g_sensorWhoAmI;
    xfer.dataSize       = 1U;
    xfer.flags          = 0U;              /* kLPI2C_TransferDefaultFlag equivalent */

    /* Execute blocking transfer */
    status = LPI2C_MasterTransferBlocking(LPI2C1, &xfer);
    if (status != kStatus_Success)
    {
        /* LPI2C read transfer failed */
        while (1) {}
    }

    /* Result is successfully stored in g_sensorWhoAmI */
    while (1)
    {
        /* Main application loop */
    }

    return 0;
}

