#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpuart.h"

int main(void)
{
    status_t status;
    uint8_t ch;

    /* 1. Configure LPUART1 root clock
       Source: 24MHz OSC, Divider: 1 -> 24 MHz peripheral clock */
    clock_root_config_t lpuart1RootConfig = {
        .clockSource = kCLOCK_RootClockSourceOsc24M,
        .divider     = 1U
    };
    CLOCK_SetRootClockConfig(kCLOCK_Root_Lpuart1, &lpuart1RootConfig);

    /* 2. Configure Pin Mux for TX (GPIO_AD_24) and RX (GPIO_AD_25) */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_LPUART1_TXD, 0U);
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_LPUART1_RXD, 0U);

    /* 3. Configure Pad Settings
       DSE=7 (max drive strength), SPEED=3, ODE=0 (no open drain), HYS=0 */
    const uint32_t uartPadConfig = 0x110F0U;
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_24_LPUART1_TXD, uartPadConfig);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_25_LPUART1_RXD, uartPadConfig);

    /* 4. Initialize LPUART with default settings */
    lpuart_config_t config;
    LPUART_GetDefaultConfig(&config);
    config.baudRate_Bps    = 115200U;
    config.parityMode      = kLPUART_ParityDisabled;
    config.dataBitsCount   = kLPUART_EightDataBits;
    config.stopBitCount    = kLPUART_OneStopBit;

    /* Init peripheral using the configured root clock frequency */
    status = LPUART_Init(LPUART1, &config, CLOCK_GetRootClockFreq(kCLOCK_Root_Lpuart1));
    if (status != kStatus_Success)
    {
        /* Halt on initialization failure */
        while (1) { }
    }

    /* 5. Echo loop: read one byte, write it back immediately */
    while (1)
    {
        if (LPUART_ReadBlocking(LPUART1, &ch, 1U) == kStatus_Success)
        {
            LPUART_WriteBlocking(LPUART1, &ch, 1U);
        }
    }

    return 0;
}

