    config.dataBitsCount = kLPUART_EightDataBits;
    config.stopBitCount  = kLPUART_OneStopBit;

    /* Initialize LPUART. Assumes OSC24M is the root clock source (RT1176 boot default). */
    status_t status = LPUART_Init(LPUART1, &config, 24000000U);
    if (status != kStatus_Success)
    {
        while (1) { }
    }

    /* Echo loop: read one byte, write it back immediately */
    while (1)
    {
        if (LPUART_ReadBlocking(LPUART1, &ch, 1U) == kStatus_Success)
        {
            LPUART_WriteBlocking(LPUART1, &ch, 1U);
        }
    }

    return 0;
}

